// The living background: a few warehouse objects (cartons, parcels, SKU tags, labels, bin outlines, route markers) drifting on three depth
// layers behind the page. One <canvas>, a seeded layout (same every load, never regenerated by React), CSS-var colours so both themes work.
//   - far / middle / near layers drift and scroll at different speeds (parallax)
//   - objects ease gently away from the pointer (spring, no state, no re-render)
//   - fewer objects on small screens, no pointer response on touch, a single static frame under reduced motion
//   - pointer-events: none; it sits behind everything and never causes overflow
import { useEffect, useRef } from "react";
import { useTheme } from "../theme.js";
import { useReducedMotion } from "./hooks.js";
import { story } from "./story.js";

const mulberry = (a) => () => {
  a |= 0;
  a = (a + 0x6d2b79f5) | 0;
  let t = Math.imul(a ^ (a >>> 15), 1 | a);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};

// layer: scroll factor, drift speed (px/s), pointer push (px), size range, alpha
const LAYERS = [
  { scroll: 0.05, drift: 5, push: 6, size: [14, 24], alpha: 0.55, types: ["parcel", "grid", "label", "bin"] },
  { scroll: 0.13, drift: 9, push: 15, size: [24, 40], alpha: 0.9, types: ["carton", "tag", "label", "route", "parcel"] },
  { scroll: 0.26, drift: 14, push: 28, size: [90, 150], alpha: 0.42, types: ["carton", "parcel"] },
];
const COUNTS = { desktop: [10, 8, 3], tablet: [7, 5, 2], mobile: [4, 3, 0] };

function build(kind) {
  const rnd = mulberry(20260101);
  const out = [];
  COUNTS[kind].forEach((n, li) => {
    const L = LAYERS[li];
    for (let i = 0; i < n; i++) {
      const ang = (-0.55 + rnd() * 0.3) * Math.PI; // short diagonal drifts
      out.push({
        li,
        type: L.types[Math.floor(rnd() * L.types.length)],
        x: rnd(),
        y: rnd(),
        s: L.size[0] + rnd() * (L.size[1] - L.size[0]),
        dx: Math.cos(ang) * L.drift * (0.6 + rnd() * 0.8),
        dy: Math.sin(ang) * L.drift * (0.6 + rnd() * 0.8) * -1,
        rot: (rnd() - 0.5) * 0.9,
        spin: (rnd() - 0.5) * 0.02,
        code: String(100 + Math.floor(rnd() * 899)),
        ox: 0,
        oy: 0,
        or: 0,
      });
    }
  });
  return out;
}

const COLORS = {
  light: { line: "#6b7a70", fill: "#c7a06a", tape: "#b98d52", green: "#008b68", orange: "#d89545", text: "#4f5c54" },
  dark: { line: "#9db2a4", fill: "#b38e5a", tape: "#d2a96c", green: "#35b08c", orange: "#e1a15a", text: "#a3b2a8" },
};

// Layer 1: a very faint warehouse grid with a few location coordinates. Moves least (0.03 of the scroll).
const CELL = 112;
function drawGrid(c, W, H, sy, col, theme) {
  const off = (sy * 0.03) % CELL;
  c.save();
  c.globalAlpha = theme === "dark" ? 0.1 : 0.14;
  c.strokeStyle = col.line;
  c.lineWidth = 1;
  c.beginPath();
  for (let x = 0; x <= W; x += CELL) { c.moveTo(x + 0.5, 0); c.lineTo(x + 0.5, H); }
  for (let y = -off; y <= H; y += CELL) { c.moveTo(0, y + 0.5); c.lineTo(W, y + 0.5); }
  c.stroke();
  c.globalAlpha = theme === "dark" ? 0.4 : 0.45;
  c.fillStyle = col.text;
  c.font = "500 10px ui-monospace, Consolas, monospace";
  for (let i = 0, x = CELL; x < W; x += CELL * 3, i++) {
    const y = ((i * 2 + 1) * CELL - off + H * 4) % H;
    c.fillText(`ref A${(i % 9) + 1}-${String(((i * 7) % 20) + 1).padStart(2, "0")}`, x + 6, y + 14);
  }
  c.restore();
}

function drawObj(c, o, s, col, a) {
  c.save();
  c.translate(o.px, o.py);
  c.rotate(o.rot + o.or);
  c.globalAlpha = a;
  c.lineWidth = 1.5;
  c.strokeStyle = col.line;
  c.fillStyle = col.fill;
  const k = o.s;
  switch (o.type) {
    case "carton": {
      // isometric box: top face, left face, right face
      const w = k, h = k * 0.55, d = k * 0.5;
      c.beginPath(); c.moveTo(0, -h); c.lineTo(w / 2, -h + d / 2); c.lineTo(0, -h + d); c.lineTo(-w / 2, -h + d / 2); c.closePath();
      c.globalAlpha = a * 0.55; c.fill(); c.globalAlpha = a; c.stroke();
      c.beginPath(); c.moveTo(-w / 2, -h + d / 2); c.lineTo(-w / 2, d / 2); c.lineTo(0, d); c.lineTo(0, -h + d); c.closePath();
      c.globalAlpha = a * 0.3; c.fill(); c.globalAlpha = a; c.stroke();
      c.beginPath(); c.moveTo(w / 2, -h + d / 2); c.lineTo(w / 2, d / 2); c.lineTo(0, d); c.lineTo(0, -h + d); c.closePath();
      c.globalAlpha = a * 0.15; c.fill(); c.globalAlpha = a; c.stroke();
      c.strokeStyle = col.tape; c.beginPath(); c.moveTo(0, -h); c.lineTo(0, -h + d); c.stroke(); // tape seam
      break;
    }
    case "parcel": {
      c.globalAlpha = a * 0.35; c.fillRect(-k / 2, -k * 0.3, k, k * 0.6); c.globalAlpha = a;
      c.strokeRect(-k / 2, -k * 0.3, k, k * 0.6);
      c.strokeStyle = col.tape; c.beginPath(); c.moveTo(-k / 8, -k * 0.3); c.lineTo(-k / 8, k * 0.3); c.moveTo(k / 8, -k * 0.3); c.lineTo(k / 8, k * 0.3); c.stroke();
      break;
    }
    case "tag": {
      c.beginPath(); c.moveTo(-k * 0.5, -k * 0.25); c.lineTo(k * 0.35, -k * 0.25); c.lineTo(k * 0.5, 0); c.lineTo(k * 0.35, k * 0.25); c.lineTo(-k * 0.5, k * 0.25); c.closePath(); c.stroke();
      c.beginPath(); c.arc(-k * 0.34, 0, k * 0.05, 0, 6.3); c.stroke();
      c.fillStyle = col.text; c.font = `600 ${Math.max(8, k * 0.2)}px ui-monospace, Consolas, monospace`; c.textBaseline = "middle"; c.fillText(`sample ${o.code}`, -k * 0.22, 1);
      break;
    }
    case "label": {
      c.strokeRect(-k * 0.5, -k * 0.3, k, k * 0.6);
      c.fillStyle = col.line;
      for (let i = 0; i < 9; i++) c.fillRect(-k * 0.42 + i * k * 0.095, -k * 0.12, (i % 3 === 0 ? 2.2 : 1.2), k * 0.3);
      c.fillStyle = col.green; c.fillRect(-k * 0.42, -k * 0.24, k * 0.22, 2.5);
      break;
    }
    case "bin": {
      c.strokeRect(-k * 0.5, -k * 0.35, k, k * 0.7);
      c.beginPath(); c.moveTo(-k * 0.5, k * 0.05); c.lineTo(k * 0.5, k * 0.05); c.stroke();
      c.fillStyle = col.orange; c.globalAlpha = a * 0.6; c.fillRect(-k * 0.3, -k * 0.2, k * 0.25, k * 0.2);
      break;
    }
    case "grid": {
      for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) c.strokeRect(-k * 0.5 + i * k * 0.36, -k * 0.5 + j * k * 0.36, k * 0.3, k * 0.3);
      break;
    }
    case "route": {
      c.strokeStyle = col.orange; c.setLineDash([4, 4]);
      c.beginPath(); c.moveTo(-k * 0.5, k * 0.2); c.lineTo(-k * 0.1, k * 0.2); c.lineTo(-k * 0.1, -k * 0.2); c.lineTo(k * 0.5, -k * 0.2); c.stroke();
      c.setLineDash([]); c.fillStyle = col.orange; c.beginPath(); c.moveTo(k * 0.5, -k * 0.2); c.lineTo(k * 0.5 - 6, -k * 0.2 - 3.5); c.lineTo(k * 0.5 - 6, -k * 0.2 + 3.5); c.closePath(); c.fill(); // arrowhead: direction of travel
      break;
    }
    default:
  }
  c.restore();
}

export default function LivingBackground() {
  const ref = useRef(null);
  const theme = useTheme();
  const reduced = useReducedMotion();

  useEffect(() => {
    const cv = ref.current;
    if (!cv) return undefined;
    const ctx = cv.getContext("2d");
    const touch = window.matchMedia?.("(pointer: coarse)").matches ?? false;
    const kind = window.innerWidth < 700 ? "mobile" : window.innerWidth < 1100 ? "tablet" : "desktop";
    const objs = build(kind);
    const col = COLORS[theme] || COLORS.light;
    let W = 0, H = 0, raf = 0, last = 0, t = 0, fade = 1;
    const pointer = { x: -9999, y: -9999 };

    const size = () => {
      const dpr = Math.min(window.devicePixelRatio || 1, 1.5);
      W = window.innerWidth;
      H = window.innerHeight;
      cv.width = Math.round(W * dpr);
      cv.height = Math.round(H * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };
    const frame = (dt, still) => {
      ctx.clearRect(0, 0, W, H);
      const sy = window.scrollY;
      drawGrid(ctx, W, H, still ? 0 : sy, col, theme);
      // fade the whole layer out during the dashboard transition
      fade += ((story.tr.active ? 0.12 : 1) - fade) * Math.min(1, dt * 5);
      for (const o of objs) {
        const L = LAYERS[o.li];
        const pad = o.s * 1.5;
        const spanX = W + pad * 2;
        const spanY = H + pad * 2;
        const wrap = (v, span) => ((v % span) + span) % span;
        o.px = wrap(o.x * spanX + (still ? 0 : o.dx * t), spanX) - pad;
        o.py = wrap(o.y * spanY + (still ? 0 : o.dy * t) - (still ? 0 : sy * L.scroll), spanY) - pad;
        let tx = 0, ty = 0, tr = 0;
        if (!still && !touch) {
          const ddx = o.px - pointer.x, ddy = o.py - pointer.y;
          const d = Math.hypot(ddx, ddy);
          const R = 140 + o.li * 40;
          if (d < R && d > 0.1) {
            const f = 1 - d / R;
            tx = (ddx / d) * L.push * f;
            ty = (ddy / d) * L.push * f;
            tr = (ddx > 0 ? 1 : -1) * 0.06 * f;
          }
        }
        const k = Math.min(1, dt * 6); // spring-like ease toward the target offset
        o.ox += (tx - o.ox) * k;
        o.oy += (ty - o.oy) * k;
        o.or += (tr - o.or) * k;
        o.rot += still ? 0 : o.spin * dt;
        const x = o.px, y = o.py;
        o.px = x + o.ox;
        o.py = y + o.oy;
        drawObj(ctx, o, 1, col, L.alpha * (theme === "dark" ? 0.8 : 0.95) * fade);
        o.px = x;
        o.py = y;
      }
    };

    size();
    if (reduced) {
      frame(0, true); // one static composition
    } else {
      const loop = (now) => {
        const dt = Math.min(0.05, (now - last) / 1000 || 0);
        last = now;
        t += dt;
        if (!document.hidden) frame(dt, false);
        raf = requestAnimationFrame(loop);
      };
      raf = requestAnimationFrame(loop);
    }
    const onMove = (e) => {
      pointer.x = e.clientX;
      pointer.y = e.clientY;
    };
    const onLeave = () => {
      pointer.x = pointer.y = -9999;
    };
    const onResize = () => {
      size();
      if (reduced) frame(0, true);
    };
    if (!touch && !reduced) {
      window.addEventListener("pointermove", onMove, { passive: true });
      document.addEventListener("pointerleave", onLeave);
    }
    window.addEventListener("resize", onResize);
    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("pointermove", onMove);
      document.removeEventListener("pointerleave", onLeave);
      window.removeEventListener("resize", onResize);
    };
  }, [theme, reduced]);

  return <canvas ref={ref} className="l-bg" aria-hidden="true" />;
}
